import { execFileSync } from "node:child_process";
import process from "node:process";

// 1) 환경 점검: Python의 sys.version · shutil.which("ffmpeg") · nvidia-smi 에 해당
function probe(cmd, args) {
  try {
    return execFileSync(cmd, args, { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).split("\n")[0];
  } catch {
    return null; // 설치되어 있지 않음
  }
}
console.log(`Node        : ${process.version}`);
console.log(`FFmpeg      : ${probe("ffmpeg", ["-version"]) ?? "없음"}`);
console.log(`GPU(nvidia) : ${probe("nvidia-smi", ["-L"]) ?? "없음 (CPU로 실행)"}`);

// 2) 전체 파이프라인: 듣기(STT) → 생각하기(LLM) → 말하기(TTS)
// 단계 함수는 asr · agent · file 카드의 예시를 참고해 채워요.
async function timed(fn) {
  const t0 = performance.now();
  const value = await fn();
  return [value, performance.now() - t0];
}

export async function voiceAgent(inputWav, { stt, llm, tts }) {
  const timings = {};
  let userText, reply, out;
  [userText, timings.STT] = await timed(() => stt(inputWav));
  console.log(`사용자: ${userText}`);
  [reply, timings.LLM] = await timed(() => llm(userText));
  console.log(`비서  : ${reply}`);
  [out, timings.TTS] = await timed(() => tts(reply, "agent_reply.wav"));

  const total = Object.values(timings).reduce((a, b) => a + b, 0);
  for (const [k, v] of Object.entries(timings)) {
    console.log(`  ${k.padEnd(4)}: ${v.toFixed(0).padStart(7)} ms`);
  }
  console.log(`  합계: ${total.toFixed(0).padStart(7)} ms`);
  return { timings, out };
}

