// 참고용 변환 예시 — 원본은 Python 노트북 Part 2 · Part 5
import { pipeline } from "@huggingface/transformers";

// TTS: 글자 → 소리 (브라우저 내장 Web Speech API, 한국어 목소리)
export function speak(text, { lang = "ko-KR", rate = 1 } = {}) {
  return new Promise((resolve, reject) => {
    const u = new SpeechSynthesisUtterance(text);
    u.lang = lang;
    u.rate = rate; // 1 = 보통, 1.3 = 30% 빠르게
    u.onend = () => resolve();
    u.onerror = (e) => reject(new Error(e.error));
    speechSynthesis.speak(u);
  });
}

// ASR: 소리 → 글자 (Whisper를 브라우저에서 실행, 입력은 16kHz mono Float32Array)
const asr = await pipeline("automatic-speech-recognition", "onnx-community/whisper-small");

export async function transcribe(audio) {
  const t0 = performance.now();
  const out = await asr(audio, {
    language: "korean",
    task: "transcribe",
    return_timestamps: true,
  });
  const elapsed = (performance.now() - t0) / 1000;
  return { text: out.text.trim(), chunks: out.chunks ?? [], elapsed };
}

// 입력(글자) → 출력(소리) → 다시 입력(소리) → 출력(글자)
await speak("안녕하세요. 음성 AI 전문가 과정에 오신 것을 환영합니다.");

