// 참고용 변환 예시 — 원본은 Python 노트북 Part 3
// 오디오를 16kHz mono로 디코딩해 샘플 수·길이·범위를 보고 파형을 그려요.
export async function loadAudio(url, sampleRate = 16000) {
  const ctx = new AudioContext({ sampleRate });
  const buf = await ctx.decodeAudioData(await (await fetch(url)).arrayBuffer());
  return { y: buf.getChannelData(0), sr: buf.sampleRate }; // Float32Array
}

export function describe(y, sr) {
  let min = Infinity;
  let max = -Infinity;
  for (const v of y) {
    if (v < min) min = v;
    if (v > max) max = v;
  }
  const seconds = y.length / sr; // 빈칸 3: 샘플 수 ÷ 1초당 측정 횟수
  console.log(
    `샘플 수: ${y.length.toLocaleString()} | 샘플링 레이트: ${sr} Hz | ` +
      `길이: ${seconds.toFixed(2)}초 | 범위: [${min.toFixed(3)}, ${max.toFixed(3)}]`,
  );
  return seconds;
}

// 파형: 픽셀 한 줄마다 구간의 최솟값~최댓값을 세로선으로 그림
export function drawWaveform(canvas, y) {
  const g = canvas.getContext("2d");
  const { width: w, height: h } = canvas;
  const step = Math.ceil(y.length / w);
  g.clearRect(0, 0, w, h);
  g.strokeStyle = "#1E9E8F";
  for (let x = 0; x < w; x++) {
    const seg = y.subarray(x * step, (x + 1) * step);
    if (!seg.length) break;
    g.beginPath();
    g.moveTo(x, ((1 - Math.max(...seg)) * h) / 2);
    g.lineTo(x, ((1 - Math.min(...seg)) * h) / 2);
    g.stroke();
  }
}

const { y, sr } = await loadAudio("sample.wav");
describe(y, sr);

