// 참고용 변환 예시 — 원본은 Python 노트북 Part 4
// 브라우저 마이크로 녹음 → 16kHz mono Float32Array (노트북 안의 JavaScript와 같은 흐름)
export async function record(seconds = 5) {
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  const recorder = new MediaRecorder(stream);
  const chunks = [];
  recorder.ondataavailable = (e) => chunks.push(e.data);
  const stopped = new Promise((resolve) => (recorder.onstop = resolve));

  recorder.start();
  await new Promise((r) => setTimeout(r, seconds * 1000));
  recorder.stop();
  await stopped;
  stream.getTracks().forEach((t) => t.stop()); // 마이크 끄기
  return new Blob(chunks, { type: recorder.mimeType }); // 보통 webm
}

// webm → 16kHz mono 샘플 (Python의 to_wav16k 역할)
export async function toSamples16k(blob) {
  const ctx = new AudioContext({ sampleRate: 16000 }); // 브라우저가 리샘플링
  const buf = await ctx.decodeAudioData(await blob.arrayBuffer());
  await ctx.close();
  return buf.getChannelData(0);
}

