// 참고용 변환 예시 — 원본은 Python 노트북 Part 5 (CER)
// jiwer 대신 편집 거리를 직접 구현해요.
export function normalizeKo(s) {
  return s.replace(/[^\p{L}\p{N}\s_]/gu, "").replace(/\s+/g, ""); // 문장부호·공백 제거
}

// 편집 거리: 정답을 결과로 바꾸는 최소 고침 횟수 (대체·삭제·삽입 각 1)
function editDistance(ref, hyp) {
  let prev = Array.from({ length: hyp.length + 1 }, (_, j) => j);
  for (let i = 1; i <= ref.length; i++) {
    const cur = [i];
    for (let j = 1; j <= hyp.length; j++) {
      const cost = ref[i - 1] === hyp[j - 1] ? 0 : 1;
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost);
    }
    prev = cur;
  }
  return prev[hyp.length];
}

// CER = 고침 횟수 ÷ 정답 글자 수
export function cer(ref, hyp) {
  const r = [...ref]; // 글자 단위 (이모지·한글 안전)
  return editDistance(r, [...hyp]) / r.length;
}

const ref = "오늘날씨좋다"; // 정답
const hyp = "오날시좋다요"; // 인식 결과
console.log(`CER = ${(cer(ref, hyp) * 100).toFixed(0)}%`); // 50%
console.log("정답입니다!", Math.abs(cer(ref, hyp) - 0.5) < 1e-9);

