// 참고용 변환 예시 — 원본은 Python 노트북 Part 6
import Anthropic from "@anthropic-ai/sdk";

const LLM_MODEL = "claude-haiku-4-5-20251001"; // 빠른 응답용 경량 모델
const SYSTEM_PROMPT =
  "당신은 친절한 한국어 음성 비서입니다. 답변은 TTS로 읽히므로 " +
  "마크다운, 목록, 이모지, 괄호를 쓰지 말고 1~2문장의 짧은 구어체로 답하세요.";

function ruleBasedReply(text) {
  const kst = new Date(Date.now() + 9 * 3600 * 1000); // UTC+9
  if (text.includes("시") && (text.includes("몇") || text.includes("시간"))) {
    return `지금은 ${kst.getUTCHours()}시 ${kst.getUTCMinutes()}분입니다.`;
  }
  if (text.includes("이름")) return "저는 음성 AI 과정 실습용 비서입니다.";
  return `'${text}'라고 말씀하셨네요. 잘 들었습니다.`;
}

// 생각하기: 글자 → 답변 (API 키가 없으면 규칙 기반)
export async function llmReply(userText) {
  const t0 = performance.now();
  let reply;
  if (process.env.ANTHROPIC_API_KEY) {
    const client = new Anthropic(); // 키는 환경 변수에서 읽음
    const msg = await client.messages.create({
      model: LLM_MODEL,
      max_tokens: 200,
      system: SYSTEM_PROMPT,
      messages: [{ role: "user", content: userText }],
    });
    reply = msg.content.map((b) => (b.type === "text" ? b.text : "")).join("");
  } else {
    reply = ruleBasedReply(userText);
  }
  return [reply, (performance.now() - t0) / 1000];
}

// 빈칸 6: 함수 세 개로 비서 조립 — 듣기(stt) → 생각하기(llmReply) → 말하기(tts)
export async function myAgent(inputWav, { stt, tts }) {
  const userText = await stt(inputWav);
  const [reply] = await llmReply(userText);
  const out = await tts(reply, "my_agent.wav");
  return { userText, reply, out };
}

